  setIsGeneratingQR(true);
  setQrCodeError('');

  try {
    const backendUrl = process.env.REACT_APP_BACKEND_URL || 'https://example.com/api';
    const shopId = whatsappConfig.phoneNumber.replace(/\D/g, ''); // Use phone number as instance ID

