// Generate QR code for WhatsApp connection using Evolution API
const handleGenerateQR = async () => {
  setIsGeneratingQR(true);
  setQrCodeError('');

  try {
    const backendUrl = process.env.REACT_APP_BACKEND_URL || 'https://example.com/api';
    const phoneNumber = whatsappConfig.phoneNumber.replace(/\D/g, '');
    const instanceName = `shop_${phoneNumber}`; // Use shop_ prefix with phone number as instance name

    // Make API call to the backend to generate QR code via Evolution API
    const response = await fetch(`${backendUrl}/whatsapp/generate-qr`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        phoneNumber: phoneNumber,
        instanceName: instanceName
      })
    });

    if (!response.ok) {
      throw new Error(`API responded with status ${response.status}`);
    }

    const data = await response.json();

    if (data.qrBase64) {
      // Direct base64 QR code from Evolution API
      setQrCodeURL(data.qrBase64);
      setQrDialogOpen(true);

      // Update the WhatsApp config with instance name for later reference
      handleWhatsAppChange('instanceName', instanceName);
    } else {
      throw new Error('QR code not found in response');
    }
  } catch (error) {
    console.error('Error generating QR code:', error);
    setQrCodeError('Falha ao gerar o QR code. Verifique se o número de telefone está correto e se a Evolution API está disponível.');
  } finally {
    setIsGeneratingQR(false);
  }
};

