// src/pages/TestEnvironment.jsx
import React, { useEffect, useMemo, useState } from 'react';
import PropTypes from 'prop-types';
import {
  AppBar,
  Box,
  Dialog,
  IconButton,
  Toolbar,
  Typography,
  CssBaseline,
} from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';

import FullCalendar        from '@fullcalendar/react';
import dayGridPlugin       from '@fullcalendar/daygrid';
import timeGridPlugin      from '@fullcalendar/timegrid';
import interactionPlugin   from '@fullcalendar/interaction';

import FloatingChat        from '../components/chat/FloatingChat';
import ChatToggleButton    from '../components/chat/ChatToggleButton';
import AppointmentDialog   from '../components/appointment/AppointmentDialog';
import Footer              from '../components/common/Footer';

import { useConfig }       from '../context/ConfigContext';
import { useNotification } from '../components/ui/NotificationContext';

import useWorkers          from '../hooks/useWorkers';      // ← NEW HOOK
import {
  fetchAppointments,
  bookAppointment,
} from '../services/api';

/* ─────────────────────────────────────────────────────────── */

export default function TestEnvironment({ open, onClose, isEnterpriseAccount }) {
  /* business config & helpers */
  const { config }          = useConfig();
  const { showNotification} = useNotification();

  /* workers come from the shared hook */
  const { workers, loading: loadingWorkers } = useWorkers();

  /* appointments local state */
  const [appointments,   setAppointments]   = useState([]);
  const [loadingAppts,   setLoadingAppts]   = useState(true);

  /* UI state */
  const [isChatOpen,     setIsChatOpen]     = useState(false);
  const [dialogOpen,     setDialogOpen]     = useState(false);
  const [selectedDate,   setSelectedDate]   = useState('');

  /* ── 1. load appointments once ░░░░░░░░░░░░░░░░░░░░░░░░░░ */
  const loadAppointments = async () => {
    setLoadingAppts(true);
    try {
      const data = await fetchAppointments();
      setAppointments(Array.isArray(data) ? data : []);
    } catch (err) {
      console.error(err);
      showNotification('Erro ao carregar agendamentos', 'error');
    } finally {
      setLoadingAppts(false);
    }
  };

  useEffect(() => { loadAppointments(); }, []);

  /* ── 2. helper: colour per worker ░░░░░░░░░░░░░░░░░░░░░░░░ */
  const getColorForWorker = React.useCallback(
    (id) => workers.find(
      b => String(b.worker_id) === String(id)
    )?.color || '#0099FF',
    [workers]
  );

  /* ── 3. format events for FullCalendar ░░░░░░░░░░░░░░░░░░░░ */
  const calendarEvents = useMemo(() => {
    const groups = {};   // key = 2025-04-30T09:00

    /* group same-time appointments first */
    appointments.forEach(a => {
      const k = `${a.date}T${a.start_time}`;
      (groups[k] = groups[k] || []).push(a);
    });

    return appointments.map((a) => {
      const start  = new Date(`${a.date}T${a.start_time}`);
      const end    = new Date(start.getTime() +
                    (a.duration || config.business.appointmentDuration) * 60_000);

      const same   = groups[`${a.date}T${a.start_time}`];
      const idx    = same.indexOf(a);

      const worker = workers.find(b => String(b.worker_id) === String(a.worker_id));
      const title  = `${worker?.name || 'Profissional'}: ${a.client_name}`;

      return ({
        id:            a.id || `${a.date}-${a.start_time}-${a.worker_id}`,
        title,
        start,
        end,
        backgroundColor: getColorForWorker(a.worker_id),
        borderColor:     getColorForWorker(a.worker_id),
        extendedProps: {
          offsetIndex:    idx,
          totalSameTime:  same.length,
        },
      });
    });
  }, [appointments, workers, getColorForWorker, config.business]);

  /* ── 4. booking from Chat / Dialog ░░░░░░░░░░░░░░░░░░░░░░░ */
  const handleNewAppointment = async (data) => {
    const res = await bookAppointment(data);
    if (res?.success) {
      // 1) create a calendar-ready object
      const newAppt = {
        ...data,
        id: res.id || `${data.date}-${data.start_time}-${data.worker_id}`,
        duration: config.business.appointmentDuration,   // if your API doesn’t return it
      };

      // 2) append to existing appointments
      setAppointments(prev => [...prev, newAppt]);

      showNotification('Agendamento criado com sucesso!', 'success');
      return { success: true };
    }
    return { error: res.error || 'Erro ao agendar' };
  };


  /* ── 5. render helpers ░░░░░░░░░░░░░░░░░░░░░░░░░░░░░░░░░ */
  const renderEventContent = ({ event, view }) => (
    <div style={{
      background: event.backgroundColor,
      padding:    '2px 4px',
      borderLeft: `4px solid ${event.backgroundColor}`,
      borderRadius: 3,
      color: '#fff',
      fontSize: view.type === 'dayGridMonth' ? '0.75rem' : '0.85rem',
    }}>
      {view.type === 'dayGridMonth'
        ? <>{event.title}</>
        : <strong>{event.title}</strong>}
    </div>
  );

  const busy = loadingWorkers || loadingAppts;

  /* ───────────────────────────────────────────────────────── */

  return (
    <Dialog fullScreen open={open} onClose={onClose}>
      {/* App bar */}
      <AppBar sx={{ position: 'relative' }}>
        <Toolbar>
          <Typography sx={{ flex: 1 }} variant="h6">
            Ambiente de Teste – {isEnterpriseAccount ? 'Modo Empresarial' : 'Modo Individual'}
          </Typography>
          <IconButton edge="end" color="inherit" onClick={onClose}>
            <CloseIcon />
          </IconButton>
        </Toolbar>
      </AppBar>

      {/* Body */}
      <Box sx={{ position:'relative', height:'calc(100vh - 64px)' }}>
        {busy ? (
          /* little spinner */
          <Box sx={{
            height:'100%', display:'flex', alignItems:'center', justifyContent:'center'
          }}>
            <Box sx={{
              width:40, height:40, borderRadius:'50%',
              border:'3px solid', borderColor: config.theme.primaryColor,
              borderTopColor:'transparent',
              animation:'spin 1s linear infinite',
              '@keyframes spin': { '100%':{ transform:'rotate(360deg)' } }
            }}/>
          </Box>
        ) : (
          <FullCalendar
            plugins={[dayGridPlugin,timeGridPlugin,interactionPlugin]}
            initialView="dayGridMonth"
            height="100%"
            headerToolbar={{
              left:'prev,next today',
              center:'title',
              right:'dayGridMonth,timeGridWeek,timeGridDay',
            }}
            events={calendarEvents}
            slotMinTime="07:00:00"
            slotMaxTime="19:00:00"
            dateClick={(info)=>{ setSelectedDate(info.dateStr); setDialogOpen(true);} }
            eventContent={renderEventContent}
            buttonText={{ today:'Hoje', month:'Mês', week:'Semana', day:'Dia' }}
          />
        )}

        {/* chat & dialogs */}
        <ChatToggleButton onClick={()=>setIsChatOpen(p=>!p)}/>
        <FloatingChat
          open={isChatOpen}
          onClose={()=>setIsChatOpen(false)}
          onNewAppointment={handleNewAppointment}
          workers={workers}
          isEnterpriseAccount={isEnterpriseAccount}
        />
        <AppointmentDialog
          open={dialogOpen}
          onClose={()=>setDialogOpen(false)}
          dateTime={selectedDate}
          refreshAppointments={loadAppointments}
          workers={workers}
        />
      </Box>
    </Dialog>
  );
}

/* ─────────────────────────────────────────────────────────── */
TestEnvironment.propTypes = {
  open:               PropTypes.bool.isRequired,
  onClose:            PropTypes.func.isRequired,
  isEnterpriseAccount:PropTypes.bool,
};

import React from 'react';
import { Box, Typography, Container, useTheme } from '@mui/material';

/**
 * Modern footer component with logo and branding
 * Uses Cognito CSS Template style classes
 * @returns {JSX.Element} Footer component with Aisol branding
 */
const Footer = () => {
  const theme = useTheme();

  return (
    <Box
      component="footer"
      sx={{
        py: 2,
        px: 2,
        mt: 'auto',
        backgroundColor: '#f9f9f9',
        borderTop: '1px solid rgba(0, 0, 0, 0.05)',
        boxShadow: '0px -2px 10px rgba(0, 0, 0, 0.02)',
      }}
      className="background-customizable"
    >
      <Container maxWidth="lg">
        <Box
          sx={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            flexWrap: 'wrap',
            gap: 2,
          }}
          className="redirect-customizable"
        >
          {/* Logo with green tint - using text as fallback if image is missing */}
          <Box
            sx={{
              height: 24,
              display: 'flex',
              alignItems: 'center',
              color: '#19BF00', // Green color matching the filter
              fontWeight: 'bold',
              fontSize: '1.2rem'
            }}
          >
            AISOL
          </Box>

          <Typography 
            variant="body2" 
            align="center"
            className="legalText-customizable"
            sx={{
              fontWeight: 500,
              letterSpacing: 0.5,
            }}
          >
            Powered by Aisol@2025
          </Typography>
        </Box>
      </Container>
    </Box>
  );
};

export default Footer;

// src/pages/LoginPage.js
import React, { useState, useEffect } from 'react';
import {
  Box,
  Paper,
  Typography,
  Button,
  Container,
  Alert,
  Card,
  CardMedia,
  Stack,
} from '@mui/material';
import {jwtDecode} from 'jwt-decode';
import { useConfig } from '../context/ConfigContext';
import AdminPage from './AdminPage';

export default function LoginPage() {
  const [error, setError]           = useState('');
  const [ready, setReady]           = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const { setUserRole }             = useConfig();

  const COGNITO_DOMAIN = process.env.REACT_APP_COGNITO_DOMAIN;
  const COGNITO_CLIENT = process.env.REACT_APP_COGNITO_CLIENT_ID;
  const REDIRECT_URI   = process.env.REACT_APP_REDIRECT_URI;
  const SCOPES         = 'openid email phone';

  // Called once we have a valid id_token
  const finishLogin = idToken => {
    try {
      const payload     = jwtDecode(idToken);
      const accountType = payload['custom:accountType'] || 'individual';
      const username    = payload['cognito:username'];

      sessionStorage.setItem('idToken',  idToken);
      sessionStorage.setItem('shopId',    username);
      sessionStorage.setItem('userRole',  accountType);

      setUserRole(accountType);
      setIsLoggedIn(true);
      setReady(true);
    } catch (e) {
      setError('Falha ao processar token: ' + e.message);
      setReady(true);
    }
  };

  // On mount: check for stored token or #id_token in hash
  useEffect(() => {
    // 1) Already logged in?
    const stored = sessionStorage.getItem('idToken');
    if (stored) {
      finishLogin(stored);
      return;
    }

    // 2) Look for id_token in URL hash
    const hash = window.location.hash;
    if (hash.includes('id_token=')) {
      const idToken = new URLSearchParams(hash.slice(1)).get('id_token');
      if (idToken) {
        // remove the hash
        window.history.replaceState({}, document.title, window.location.pathname);
        finishLogin(idToken);
        return;
      } else {
        setError('Nenhum id_token encontrado na resposta.');
      }
    }

    // 3) Not logged in yet — show login button
    setReady(true);
  }, [setUserRole]);

  // If we have a token and are “ready,” show the app
  if (ready && isLoggedIn) {
    return <AdminPage />;
  }

  // Otherwise, show the Entrar button for implicit flow
  const handleHostedUi = () => {
    const params = new URLSearchParams({
      response_type: 'token',
      client_id:     COGNITO_CLIENT,
      redirect_uri:  REDIRECT_URI,
      scope:         SCOPES,
      screen_hint:   'signup',  // optional: jump straight to the sign-up form
      lang:          'pt-BR',   // Portuguese localization
    });
    window.location.assign(
      `${COGNITO_DOMAIN}/oauth2/authorize?${params.toString()}`
    );
  };

  return (
    <Box className="background-customizable" sx={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
      <Container maxWidth="sm">
        <Paper elevation={3} sx={{ width: '100%', p: 4, borderRadius: 2 }}>
          <Stack spacing={3}>
            <Box className="banner-customizable" sx={{ textAlign: 'center', borderRadius: 2, overflow: 'hidden', mb: 2, pt: 3, pb: 3 }}>
              <Typography
                variant="h3"
                sx={{
                  fontWeight: 'bold',
                  color: '#19BF00', // Green color
                  margin: '20px auto'
                }}
                className="logo-customizable"
              >
                AISOL
              </Typography>
            </Box>

            <Typography variant="h4" align="center" fontWeight="bold">
              WhatsApp Business Assistant
            </Typography>

            <Typography variant="body1" align="center" color="text.secondary" className="textDescription-customizable">
              Clique abaixo para entrar via Amazon Cognito.
            </Typography>

            {error && <Alert severity="error" className="errorMessage-customizable">{error}</Alert>}

            <Button
              onClick={handleHostedUi}
              variant="contained"
              size="large"
              fullWidth
              className="submitButton-customizable"
              sx={{ mt: 2 }}
            >
              Entrar
            </Button>

            <Box sx={{ mt: 2, textAlign: 'center' }} className="redirect-customizable">
              <Typography variant="caption" color="text.secondary" className="legalText-customizable">
                Não tem conta? Use a Hosted-UI do Cognito para se cadastrar.
              </Typography>
            </Box>
          </Stack>
        </Paper>

        {/* Footer */}
        <Box 
          sx={{ 
            mt: 4, 
            textAlign: 'center',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            gap: 1
          }}
        >
          <Box
            sx={{
              height: '24px',
              display: 'flex',
              alignItems: 'center',
              color: '#19BF00', // Green color
              fontWeight: 'bold',
              fontSize: '1rem'
            }}
          >
            AISOL
          </Box>
          <Typography variant="body2" className="legalText-customizable">
            Powered by Aisol@2025
          </Typography>
        </Box>
      </Container>
    </Box>
  );
}

