   1	import React, { useState, useEffect, useRef } from 'react';
   2	import PropTypes from 'prop-types';
   3	import { 
   4	  Box, 
   5	  TextField, 
   6	  Button, 
   7	  Typography, 
   8	  Chip,
   9	  Stack,
  10	  Card,
  11	  CardActionArea,
  12	  CardContent
  13	} from '@mui/material';
  14	import { handleMessage, getSuggestedOptions } from '@barber-app/booking-fsm';
  15	import { BookingContext } from '@barber-app/booking-fsm';
  16	import { callChatApi } from '../../services/api';
  17	import { useNotification } from '../ui/NotificationContext';
  18	import { useConfig } from '../../context/ConfigContext';
  19	
  20	
  21	
  22	/**
  23	 * Chatbox component that allows users to book appointments via a chat interface
  24	 */
  25	export default function Chatbox({ onNewAppointment, workers, freeModeAllowed }) {
  26	  // 1) React hooks at the very top:
  27	  const { config, getUserRole } = useConfig();         // ✅ exactly one useConfig()
  28	  const isEnterpriseAccount     = getUserRole() === 'enterprise';
  29	  const shopId                  = sessionStorage.getItem('shopId');
  30	
  31	  const [messages, setMessages]           = useState([]);
  32	  const [input, setInput]                 = useState('');
  33	  const [loading, setLoading]             = useState(false);
  34	  const [showServiceOptions, setShowServiceOptions] = useState(false);
  35	  const [showWorkerOptions,  setShowWorkerOptions]  = useState(false);
  36	  const [showDateOptions,    setShowDateOptions]    = useState(false);
  37	  const [showTimeOptions,    setShowTimeOptions]    = useState(false);
  38	  const [availableTimes,     setAvailableTimes]     = useState([]);
  39	  const [availableDates,     setAvailableDates]     = useState([]);
  40	
  41	  
  42	  
  43	  
  44	  // Track booking flow state
  45	  const [ctx, setCtx] = useState(/** @type {BookingContext} */({
  46	    shop_id: sessionStorage.getItem('shopId'),
  47	    accountType: getUserRole() === 'enterprise' ? 'enterprise' : 'individual',
  48	    workers,
  49	    config,
  50	    step: 0
  51	  }));
  52	  const bookingState = ctx;
  53	  const setBookingState = setCtx;
  54	  const showConfirmOptions = ctx.step === 6;
  55	  const messagesEndRef = useRef(null);
  56	  const { showNotification } = useNotification();
  57	
  58	
  59	  // Get services from config or use defaults
  60	  const getAvailableServices = () => {
  61	    // Check if services are defined in config
  62	    if (config?.services?.items && config.services.items.length > 0) {
  63	      // Use the services from config
  64	      return config.services.items.map(service => service.name);
  65	    }
  66	    
  67	    // Fallback to default services if none are configured
  68	    return [
  69	      "Corte de cabelo",
  70	      "Barba",
  71	      "Corte e barba", 
  72	      "Sobrancelha",
  73	      "Hidratação"
  74	    ];
  75	  };
  76	  
  77	  const commonServices = getAvailableServices();
  78	  
  79	  // Helper function to get guided mode setting from config
  80	  const isGuidedMode = () => {
  81	    if (!freeModeAllowed) return true;
  82	  
  83	    const guidedMode = config?.chatbot?.guidedMode !== false; // default: guided
  84	    return guidedMode;
  85	  };
  86	
  87	  const today = new Date();
  88	  const formattedDate = today.toISOString().split('T')[0];
  89	  const workerNames = workers.length > 0 ? workers.map(b => b.name).join(', ') : 'Nenhum profissional disponível';
  90	  
  91	  // Helper function to add minutes to a time string (HH:MM)
  92	  const addMinutes = (timeStr, minutes) => {
  93	    const [hours, mins] = timeStr.split(':').map(Number);
  94	    const date = new Date();
  95	    date.setHours(hours, mins + minutes, 0);
  96	    return date.getHours().toString().padStart(2, '0') + ':' + 
  97	           date.getMinutes().toString().padStart(2, '0');
  98	  };
  99	
 100	  // Scroll to bottom of messages
 101	  const scrollToBottom = () => {
 102	    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
 103	  };
 104	
 105	  useEffect(() => {
 106	    scrollToBottom();
 107	  }, [messages]);
 108	
 109	  // Reset the chat when the chat mode changes
 110	  useEffect(() => {
 111	    resetChat();
 112	    // eslint-disable-next-line react-hooks/exhaustive-deps
 113	  }, [config?.chatbot?.guidedMode, isEnterpriseAccount]);
 114	
 115	  // Initialize prompt with system message
 116	  useEffect(() => {
 117	    if (messages.length === 0) {
 118	      if (isGuidedMode()) {
 119	        console.log("Initializing guided mode chat");
 120	        // In guided mode, start with assistant greeting
 121	        const assistantGreeting = { 
 122	          role: 'assistant', 
 123	          content: "Olá! Sou a " + (config?.assistant?.name || "Amanda") + ", assistente virtual de " + (config?.business?.name || "Barbearia Elite") + ". Para começar, poderia me informar seu nome, por favor?" 
 124	        };
 125	        setMessages([
 126	          { role: 'system', content: getPromptText() },
 127	          assistantGreeting
