 332	    // Map Portuguese day names to JavaScript day indices (0 = Sunday, 1 = Monday, etc.)
 333	    const dayMap = {
 334	      'domingo': 0,
 335	      'segunda': 1, 'segunda-feira': 1,
 336	      'terça': 2, 'terça-feira': 2,
 337	      'quarta': 3, 'quarta-feira': 3,
 338	      'quinta': 4, 'quinta-feira': 4,
 339	      'sexta': 5, 'sexta-feira': 5,
 340	      'sábado': 6
 341	    };
 342	    
 343	    const closedDayIndices = closedDays.map(day => {
 344	      const lowerDay = day.toLowerCase();
 345	      return dayMap[lowerDay] !== undefined ? dayMap[lowerDay] : -1;
 346	    }).filter(idx => idx !== -1);
 347	    
 348	    // Generate dates for the next 14 days
