 353	      // Skip closed days
 354	      if (!closedDayIndices.includes(date.getDay())) {
 355	        // Get date components in local timezone
 356	        const year = date.getFullYear();
 357	        const month = String(date.getMonth() + 1).padStart(2, '0');
