              };
              setMessages(prev => [...prev, errorResponse]);
            }
          }
        }
      } catch (error) {
        console.error('Erro ao comunicar com ChatGPT:', error);
        showNotification('Erro ao comunicar com o assistente de chat.', 'error');
      } finally {
        setLoading(false);
      }
    }
  };

  const parseAppointment = (text) => {
    try {
      const jsonStart = text.indexOf('{');
      const jsonEnd = text.lastIndexOf('}');
      if (jsonStart !== -1 && jsonEnd !== -1) {
        const jsonString = text.substring(jsonStart, jsonEnd + 1);
        const data = JSON.parse(jsonString);

        // Support both "worker_id" and "professional_id"
        const professionalIdKey = isEnterpriseAccount ? 'worker_id' : (
          data.worker_id ? 'worker_id' : 'professional_id'
        );

        if (
          data[professionalIdKey] &&
          data.date &&
          data.start_time &&
          data.date.length === 10 &&
          data.start_time.length === 5
        ) {
          // Normalize the data to use worker_id
          const normalizedData = { ...data };
          if (professionalIdKey !== 'worker_id') {
            normalizedData.worker_id = data[professionalIdKey];
            delete normalizedData[professionalIdKey];
          }

          return normalizedData;
        }
      }
    } catch (error) {
      console.error('Falha ao analisar JSON de agendamento:', error);
    }
    return null;
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  // Reset to start a new chat
  const resetChat = () => {
    setMessages([]);
    setBookingState({
      step: 0,
      clientName: '',
      selectedService: '',
      selectedWorker: null,
      selectedDate: '',
      selectedTime: ''
    });
    setShowServiceOptions(false);
    setShowWorkerOptions(false);
    setShowDateOptions(false);
    setShowTimeOptions(false);
  };

  const visibleMessages = messages.filter(msg => msg.role !== 'system');

  return (
    <Box 
      sx={{ 
        display: 'flex', 
        flexDirection: 'column', 
        height: '100%', 
        p: 1,
        bgcolor: config?.theme?.chatBubbleColor || '#f5f5f5',
        fontFamily: '"Roboto", "Helvetica", "Arial", sans-serif',
      }}
    >
      {/* Chat Header */}
      <Box
        sx={{
          display: 'flex',
          alignItems: 'center',
          gap: 1,
          p: 1,
          mb: 1,
          bgcolor: 'primary.main',
          color: 'white',
          borderRadius: '8px 8px 0 0',
          boxShadow: 1
        }}
      >
        <Box
          sx={{
            width: 40,
            height: 40,
            borderRadius: '50%',
            bgcolor: 'primary.light',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: '1.2rem',
            fontWeight: 'bold'
          }}
        >
          {config?.assistant?.name?.charAt(0) || 'A'}
        </Box>
        <Box>
          <Typography variant="subtitle1" fontWeight="bold">
            {config?.assistant?.name || 'Amanda'} - {config?.assistant?.title || 'Assistente Virtual'}
          </Typography>
          <Typography variant="caption">
            {config?.business?.name || 'Barbearia Elite'}
          </Typography>
        </Box>
      </Box>

      {/* Messages Area */}
      <Box 
        sx={{ 
          flex: 1, 
          overflowY: 'auto', 
          borderRadius: 2,
          p: 1,
          mb: 1,
          bgcolor: 'white',
          boxShadow: 'inset 0 0 5px rgba(0,0,0,0.1)',
          display: 'flex',
          flexDirection: 'column'
        }}
      >
        {/* Welcome message if no messages yet */}
        {visibleMessages.length === 0 && (
          <Box
            sx={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              height: '100%',
              color: 'text.secondary',
              textAlign: 'center',
              p: 2
            }}
          >
            <Typography variant="h6" gutterBottom>
              Bem-vindo à {config?.business?.name || 'Barbearia Elite'}
            </Typography>
            <Typography variant="body2">
              {config?.assistant?.greeting || 'Olá! Sou a Amanda, sua assistente virtual. Como posso ajudá-lo hoje?'}
            </Typography>
          </Box>
        )}

        {/* Chat messages */}
        <Box sx={{ flex: 1 }}>
          {visibleMessages.map((msg, i) => (
            <Box 
              key={i} 
              sx={{ 
                mb: 1.5, 
                display: 'flex',
                flexDirection: 'column',
                alignItems: msg.role === 'user' ? 'flex-end' : 'flex-start',
              }}
            >
              <Box
                sx={{
                  display: 'inline-block',
                  backgroundColor: msg.role === 'user' ? (config?.theme?.userMessageColor || '#1976d2') : (config?.theme?.assistantMessageColor || '#f5f5f5'),
                  color: msg.role === 'user' ? 'white' : 'text.primary',
                  p: 1.5,
                  borderRadius: msg.role === 'user' 
                    ? '18px 18px 4px 18px'
                    : '18px 18px 18px 4px',
                  maxWidth: '85%',
                  boxShadow: 1,
                  wordBreak: 'break-word',
                  whiteSpace: 'pre-wrap'
                }}
              >
                {msg.content}
              </Box>
              <Typography 
                variant="caption" 
                color="text.secondary"
                sx={{ mt: 0.5, mx: 1 }}
              >
                {msg.role === 'user' ? 'Você' : (config?.assistant?.name || 'Amanda')} • {new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
              </Typography>
            </Box>
          ))}
          <div ref={messagesEndRef} />
        </Box>

        {/* Service Options - only show in guided mode */}
        {isGuidedMode() && showServiceOptions && (
          <Box sx={{ mt: 2, mb: 2 }}>
            <Typography variant="subtitle2" color="primary" sx={{ mb: 1 }}>
              Escolha um serviço:
            </Typography>
            <Stack direction="row" spacing={1} sx={{ flexWrap: 'wrap', gap: 1 }}>
              {commonServices.map((service, index) => (
                <Chip 
                  key={index}
                  label={service}
                  onClick={() => handleServiceSelect(service)}
                  color="primary"
                  variant="outlined"
                  clickable
                  sx={{ mb: 1 }}
                />
              ))}
            </Stack>
          </Box>
        )}

        {/* Worker Options - only show in guided mode and enterprise account */}
        {isGuidedMode() && showWorkerOptions && workers.length > 0 && isEnterpriseAccount && (
          <Box sx={{ mt: 2, mb: 2 }}>
            <Typography variant="subtitle2" color="primary" sx={{ mb: 1 }}>
              Escolha um profissional:
            </Typography>
            <Stack spacing={1}>
              {workers.map((worker) => (
                <Card 
                  key={worker.worker_id}
                  variant="outlined"
                  sx={{ mb: 1 }}
                >
                  <CardActionArea onClick={() => handleWorkerSelect(worker)}>
                    <CardContent sx={{ py: 1 }}>
                      <Typography variant="subtitle1">{worker.name}</Typography>
                      {worker.specialties && worker.specialties.length > 0 && (
                        <Typography variant="body2" color="text.secondary">
                          Especialidades: {worker.specialties.join(', ')}
                        </Typography>
                      )}
                    </CardContent>
                  </CardActionArea>
                </Card>
              ))}
            </Stack>
          </Box>
        )}

        {/* Date Options - only show in guided mode */}
        {isGuidedMode() && showDateOptions && availableDates.length > 0 && (
          <Box sx={{ mt: 2, mb: 2 }}>
            <Typography variant="subtitle2" color="primary" sx={{ mb: 1 }}>
              Escolha uma data:
            </Typography>
            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
              {availableDates.map((date, index) => (
                <Chip
                  key={index}
                  label={date.display}
                  onClick={() => handleDateSelect(date)}
                  color="primary"
                  variant="outlined"
                  clickable
                  sx={{ mb: 1 }}
                />
              ))}
            </Box>
          </Box>
        )}

        {/* Time Options - only show in guided mode */}
        {isGuidedMode() && showTimeOptions && availableTimes.length > 0 && (
          <Box sx={{ mt: 2, mb: 2 }}>
            <Typography variant="subtitle2" color="primary" sx={{ mb: 1 }}>
              Escolha um horário:
            </Typography>
            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
              {availableTimes.map((time, index) => (
                <Chip
                  key={index}
                  label={time}
                  onClick={() => handleTimeSelect(time)}
                  color="primary"
                  variant="outlined"
                  clickable
                  sx={{ mb: 1 }}
                />
              ))}
            </Box>
          </Box>
        )}

        {/* ✔ / ✖ Confirmation buttons */}
        {isGuidedMode() && ctx.step === 6 && (
          <Box sx={{ mt: 2, mb: 2 }}>
            <Typography variant="subtitle2" color="primary" sx={{ mb: 1 }}>
              Confirmar agendamento?
            </Typography>
            <Stack direction="row" spacing={2}>
              <Button
                variant="contained"
                color="primary"
                onClick={() => sendMessage('sim')}
              >
                Sim
              </Button>
              <Button
                variant="outlined"
                color="primary"
                onClick={() => sendMessage('não')}
              >
                Não
              </Button>
            </Stack>
          </Box>
        )}

      </Box>

      {/* Input Area */}
      <Box 
        sx={{ 
          display: 'flex', 
          gap: 1,
          p: 1,
          bgcolor: 'white',
          borderRadius: '0 0 8px 8px',
          boxShadow: 1
        }}
      >
        <TextField
          fullWidth
          placeholder={loading ? "Processando resposta..." : "Digite sua mensagem..."}
          value={input}
          onChange={e => setInput(e.target.value)}
          onKeyPress={handleKeyPress}
          disabled={loading}
          size="small"
          variant="outlined"
          InputProps={{
            sx: {
              borderRadius: 5,
              bgcolor: '#f9f9f9'
            }
          }}
          inputProps={{
            'aria-label': 'chat message input'
          }}
          sx={{ flex: 1 }}
        />
        <Button 
          onClick={() => sendMessage()} 
          disabled={loading} 
          variant="contained"
          aria-label="send message"
          sx={{
            borderRadius: '50%',
            minWidth: '40px',
            width: '40px',
            height: '40px',
            p: 0
          }}
        >
          {loading ? 
            <Box 
              sx={{ 
                width: 24, 
                height: 24, 
                borderRadius: '50%', 
                border: '2px solid white',
                borderTop: '2px solid transparent',
                animation: 'spin 1s linear infinite',
                '@keyframes spin': {
                  '0%': { transform: 'rotate(0deg)' },
                  '100%': { transform: 'rotate(360deg)' }
                }
              }} 
            /> : 
            '➤'
          }
        </Button>
      </Box>
    </Box>
  );
}

Chatbox.propTypes = {
  onNewAppointment: PropTypes.func.isRequired,
  workers: PropTypes.arrayOf(
    PropTypes.shape({
      worker_id: PropTypes.oneOfType([PropTypes.string, PropTypes.number]).isRequired,
      name: PropTypes.string.isRequired,
    })
  ),
  isEnterpriseAccount: PropTypes.bool,   // ← add this line
  freeModeAllowed: PropTypes.bool,
};

