  1	import React, { useState } from 'react';
  2	import PropTypes from 'prop-types';
  3	import {
  4	  Dialog,
  5	  DialogTitle,
  6	  DialogContent,
  7	  DialogActions,
  8	  TextField,
  9	  Button,
 10	  Typography,
 11	  Box,
 12	  Select,
 13	  MenuItem,
 14	} from '@mui/material';
 15	import { bookAppointment } from '../../services/api';
 16	import { useNotification } from '../ui/NotificationContext';
 17	import { useConfig } from '../../context/ConfigContext';
 18	
 19	export default function AppointmentDialog({
 20	  open,
 21	  onClose,
 22	  dateTime = '',
 23	  refreshAppointments,
 24	  workers = [],
 25	}) {
 26	  const initialDate = dateTime || '';
 27	  const { showNotification } = useNotification();
 28	  const { config } = useConfig();
 29	  const [isSubmitting, setIsSubmitting] = useState(false);
 30	  const [formData, setFormData] = useState({
 31	    worker_id: '',
 32	    service_id: '',
 33	    date: initialDate,
 34	    start_time: '',
 35	    duration: config?.business?.appointmentDuration || 40,
 36	    client_name: '',
 37	  });
 38	
 39	  const handleChange = (e) => {
 40	    const { name, value } = e.target;
 41	    setFormData((prev) => ({ ...prev, [name]: value }));
 42	  };
 43	
 44	  const handleSubmit = async (e) => {
 45	    e.preventDefault();
 46	    
 47	    if (!formData.date || !formData.start_time || !formData.worker_id || !formData.service_id) {
 48	      showNotification('Por favor, preencha todos os campos obrigatórios.', 'error');
 49	      return;
 50	    }
 51	    
 52	    setIsSubmitting(true);
 53	    
 54	    try {
 55	      // Get selected service and worker information for better details
 56	      const selectedWorker = workers.find(w => w.worker_id === formData.worker_id);
 57	      const selectedService = config?.services?.items.find(s => s.id === formData.service_id);
 58	      
 59	      // Update duration based on selected service
 60	      const appointmentData = {
 61	        ...formData,
 62	        duration: selectedService?.duration || formData.duration,
 63	        worker_name: selectedWorker?.name || '',
 64	        service_name: selectedService?.name || ''
 65	      };
 66	      
 67	      await bookAppointment(appointmentData);
 68	      showNotification('Agendamento realizado com sucesso!', 'success');
 69	      onClose();
 70	      refreshAppointments();
 71	    } catch (error) {
 72	      showNotification(error.message || 'Erro ao realizar agendamento.', 'error');
 73	    } finally {
 74	      setIsSubmitting(false);
 75	    }
 76	  };
 77	
 78	  const resetForm = () => {
 79	    setFormData({
 80	      worker_id: '',
 81	      service_id: '',
 82	      date: initialDate,
 83	      start_time: '',
 84	      duration: config?.business?.appointmentDuration || 40,
 85	      client_name: '',
 86	    });
 87	  };
 88	
 89	  const handleClose = () => {
 90	    resetForm();
 91	    onClose();
 92	  };
 93	
 94	  return (
 95	    <Dialog 
 96	      open={open} 
 97	      onClose={handleClose}
 98	      PaperProps={{
 99	        sx: {
100	          borderRadius: 2,
101	          maxWidth: 500
102	        }
103	      }}
104	    >
105	      <DialogTitle sx={{ 
106	        bgcolor: config?.theme?.primaryColor || '#1976d2', 
107	        color: 'white',
108	        py: 2,
109	        fontSize: '1.5rem'
110	      }}>
111	        Agendar Novo Horário
112	      </DialogTitle>
113	      <Box component="form" onSubmit={handleSubmit}>
114	        <DialogContent dividers sx={{ p: 3 }}>
115	          <Box sx={{ mb: 3 }}>
116	            <Typography variant="subtitle1" fontWeight="bold" gutterBottom>
117	              Data
118	            </Typography>
119	            <TextField
120	              type="date"
121	              name="date"
122	              value={formData.date}
123	              onChange={handleChange}
124	              required
125	              fullWidth
126	              margin="dense"
127	              inputProps={{ 'aria-label': 'appointment date' }}
128	              InputLabelProps={{ shrink: true }}
129	              sx={{ 
130	                '& .MuiOutlinedInput-root': {
131	                  borderRadius: 2
132	                }
133	              }}
134	            />
135	          </Box>
136	
137	          <Box sx={{ mb: 3 }}>
138	            <Typography variant="subtitle1" fontWeight="bold" gutterBottom>
139	              Horário
140	            </Typography>
141	            <TextField
142	              type="time"
143	              name="start_time"
144	              value={formData.start_time}
145	              onChange={handleChange}
146	              required
147	              fullWidth
148	              margin="dense"
149	              inputProps={{ 'aria-label': 'appointment time', step: 600 }}
150	              InputLabelProps={{ shrink: true }}
151	              sx={{ 
152	                '& .MuiOutlinedInput-root': {
153	                  borderRadius: 2
154	                }
155	              }}
156	              helperText={`Os horários são disponíveis a cada ${config?.business?.appointmentInterval || 10} minutos`}
157	            />
158	          </Box>
159	
160	          <Box sx={{ mb: 3 }}>
161	            <Typography variant="subtitle1" fontWeight="bold" gutterBottom>
162	              {config?.services?.label?.singular || 'Serviço'}
163	            </Typography>
164	            <Select
165	              name="service_id"
166	              value={formData.service_id}
167	              onChange={handleChange}
168	              fullWidth
169	              required
170	              displayEmpty
171	              sx={{ 
172	                mt: 1, 
173	                '& .MuiOutlinedInput-root': {
174	                  borderRadius: 2
175	                }
176	              }}
177	              inputProps={{ 'aria-label': 'select service' }}
178	            >
179	              <MenuItem disabled value="">
180	                <em>Selecione um {config?.services?.label?.singular?.toLowerCase() || 'serviço'}</em>
181	              </MenuItem>
182	              {(config?.services?.items || []).map((service) => (
183	                <MenuItem key={service.id} value={service.id}>
184	                  {service.name} - {service.duration} min - R$ {service.price.toFixed(2)}
185	                </MenuItem>
186	              ))}
187	            </Select>
188	          </Box>
189	
190	          <Box sx={{ mb: 3 }}>
191	            <Typography variant="subtitle1" fontWeight="bold" gutterBottom>
192	              {config?.professionals?.[0]?.singular || 'Profissional'}
193	            </Typography>
194	            <Select
195	              name="worker_id"
196	              value={formData.worker_id}
197	              onChange={handleChange}
198	              fullWidth
199	              required
200	              displayEmpty
201	              sx={{ 
202	                mt: 1, 
203	                '& .MuiOutlinedInput-root': {
204	                  borderRadius: 2
205	                }
206	              }}
207	              inputProps={{ 'aria-label': 'select worker' }}
208	            >
209	              <MenuItem disabled value="">
210	                <em>Selecione um {config?.professionals?.[0]?.singular?.toLowerCase() || 'profissional'}</em>
211	              </MenuItem>
212	              {workers.map((worker) => (
213	                <MenuItem key={worker.worker_id || worker.worker_id} value={worker.worker_id || worker.worker_id}>
214	                  {worker.name}
215	                </MenuItem>
216	              ))}
217	            </Select>
218	          </Box>
219	
220	          <Box sx={{ mb: 2 }}>
221	            <Typography variant="subtitle1" fontWeight="bold" gutterBottom>
222	              Seu Nome
223	            </Typography>
224	            <TextField
225	              type="text"
226	              name="client_name"
227	              value={formData.client_name}
228	              onChange={handleChange}
229	              fullWidth
230	              margin="dense"
231	              required
232	              placeholder="Digite seu nome completo"
233	              inputProps={{ 'aria-label': 'client name' }}
234	              sx={{ 
235	                '& .MuiOutlinedInput-root': {
236	                  borderRadius: 2
237	                }
238	              }}
239	            />
240	          </Box>
241	        </DialogContent>
242	        <DialogActions sx={{ px: 3, py: 2 }}>
243	          <Button 
244	            onClick={handleClose} 
245	            disabled={isSubmitting}
246	            variant="outlined"
247	            sx={{ borderRadius: 2, px: 3 }}
248	          >
249	            Cancelar
250	          </Button>
251	          <Button 
252	            variant="contained" 
253	            type="submit"
254	            disabled={isSubmitting}
255	            sx={{ 
256	              borderRadius: 2, 
257	              px: 3,
258	              boxShadow: 2,
