   326	    const closedDays = config?.business?.closedDays || ['Domingo'];
   327	    
   328	    // Map Portuguese day names to JavaScript day indices (0 = Sunday, 1 = Monday, etc.)
   329	    const dayMap = {
   330	      'domingo': 0,
   331	      'segunda': 1, 'segunda-feira': 1,
   332	      'terça': 2, 'terça-feira': 2,
   333	      'quarta': 3, 'quarta-feira': 3,
   334	      'quinta': 4, 'quinta-feira': 4,
   335	      'sexta': 5, 'sexta-feira': 5,
   336	      'sábado': 6
   337	    };
   338	    
   339	    const closedDayIndices = closedDays.map(day => {
   340	      const lowerDay = day.toLowerCase();
   341	      return dayMap[lowerDay] !== undefined ? dayMap[lowerDay] : -1;
   342	    }).filter(idx => idx !== -1);
   343	    
   344	    // Generate dates for the next 14 days
