   346	      const date = new Date();
   347	      date.setDate(today.getDate() + i);
   348	      
   349	      // Skip closed days
   350	      if (!closedDayIndices.includes(date.getDay())) {
   351	        // Get date components in local timezone
   352	        const year = date.getFullYear();
   353	        const month = String(date.getMonth() + 1).padStart(2, '0');
   354	        const day = String(date.getDate()).padStart(2, '0');
   355	        
   356	        // Format date as YYYY-MM-DD without using toISOString() to avoid timezone issues
   357	        const formattedDate = `${year}-${month}-${day}`;
