   363	        });
   364	        
   365	        dates.push({
   366	          value: formattedDate,
   367	          display: displayDate,
   368	          jsDate: new Date(date) // Store a copy of the JS Date object for reliable formatting
   369	        });
   370	      }
   371	    }
