/* ────────────────────────────────────────────────────────────────
   4)  APPOINTMENTS – POST
   ---------------------------------------------------------------- */
export async function bookAppointment(data) {
  if (isMockMode()) return legacyMockBook(data);

  const headers = await authHeader();
  const payload = { ...data, shop_id: shopId() };

  const r = await fetch(`${API_BASE}/appointments/book`, {
    method: 'POST',
    headers,
    body: JSON.stringify(payload),
  });
  if (!r.ok) throw new Error(await r.text());

  // Generate calendar invite (ICS file)
  const response = await r.json();
  response.icsFile = generateIcsFile(data);

  return response;
}

/* ────────────────────────────────────────────────────────────────
   4.1)  Generate ICS file for calendar integration
   ---------------------------------------------------------------- */
function generateIcsFile(appointmentData) {
  // Format: YYYYMMDDTHHMMSSZ
  const startDate = new Date(`${appointmentData.date}T${appointmentData.start_time}`);
  const endDate = new Date(startDate.getTime() + (appointmentData.duration * 60 * 1000));

  const formatDateForIcs = (date) => {
    return date.toISOString().replace(/-|:|\.\d{3}/g, '');
  };

  const now = new Date();
  const businessName = getDatabaseConfig().business?.name || 'Empresa';
  const businessAddress = getDatabaseConfig().business?.address || '';

  const serviceName = appointmentData.service_name || 'Consulta';
  const workerName = appointmentData.worker_name || 'Profissional';

  const icsContent = [
    'BEGIN:VCALENDAR',
    'VERSION:2.0',
    'PRODID:-//AiSol//WhatsApp Booking//PT',
    'CALSCALE:GREGORIAN',
    'METHOD:REQUEST',
    'BEGIN:VEVENT',
    `UID:${now.getTime()}-${Math.random().toString(36).substring(2, 9)}@aisol.app`,
    `DTSTAMP:${formatDateForIcs(now)}`,
    `DTSTART:${formatDateForIcs(startDate)}`,
    `DTEND:${formatDateForIcs(endDate)}`,
    `SUMMARY:${serviceName} com ${workerName}`,
    `DESCRIPTION:Agendamento de ${serviceName} com ${workerName} em ${businessName}`,
    `LOCATION:${businessAddress}`,
    'STATUS:CONFIRMED',
    'TRANSP:OPAQUE',
    'BEGIN:VALARM',
    'ACTION:DISPLAY',
    'DESCRIPTION:Lembrete',
    'TRIGGER:-PT30M',
    'END:VALARM',
    'END:VEVENT',
    'END:VCALENDAR'
  ].join('\r\n');

  return icsContent;
}

