 27	    try {
 28	      const shop = sessionStorage.getItem('shopId') || 'demo-shop';
 29	      const storageKey = `appConfig_${shop}`;
 30	      const cfg = JSON.parse(localStorage.getItem(storageKey) || '{}');
 31	      return cfg.database || {};
 32	    } catch {
 33	      return {};
 34	    }
 35	  };
 36	  
 37	  /** Build headers with the JWT we stored after Hosted-UI login */
 38	  async function authHeader() {
 39	    const token = sessionStorage.getItem('idToken');
 40	    return {
 41	      Authorization: `Bearer ${token}`,
 42	      'Content-Type': 'application/json',
 43	    };
 44	  }
