 95	     2)  APPOINTMENTS – GET
 96	     ---------------------------------------------------------------- */
 97	  export async function fetchAppointments(dateISO) {
 98	    /* Offline / mock */
 99	    if (isMockMode()) {
100	      return mockAppointments.filter((a) => !dateISO || a.date === dateISO);
101	    }
102	  
103	    try {
104	      const headers = await authHeader();
105	      
106	      // If token is missing, return empty appointments to prevent 401 errors
107	      if (!headers.Authorization || headers.Authorization === 'Bearer undefined' || headers.Authorization === 'Bearer null') {
108	        console.warn('Missing authentication token, returning empty appointments');
109	        return [];
110	      }
111	      
112	      const base = `${API_BASE}/appointments?shop_id=${shopId()}`;
113	      const url = dateISO ? `${base}&date=${dateISO}` : base;
114	    
115	      const r = await fetch(url, { headers });
116	      if (!r.ok) {
117	        console.warn(`API responded with status ${r.status}: ${r.statusText}`);
118	        return []; // Return empty array instead of throwing
119	      }
120	      
121	      const data = await r.json();
122	      return data.appointments || [];
123	    } catch (error) {
124	      console.error('Error fetching appointments:', error);
125	      return []; // Return empty array instead of throwing
126	    }
127	  }
