183	    if (isMockMode()) {
184	      return []; // TODO: Add mock customer data when needed
185	    }
186	
187	    try {
188	      const headers = await authHeader();
189	      const r = await fetch(`${API_BASE}/customers?shop_id=${shopId()}`, { headers });
190	      
191	      if (!r.ok) throw new Error(await r.text());
192	      const data = await r.json();
193	      return data.customers || [];
194	    } catch (error) {
195	      console.error('Error fetching customers:', error);
196	      // Return empty array instead of throwing to avoid breaking UI
197	      return [];
198	    }
199	  }
