201	  /* ────────────────────────────────────────────────────────────────
202	     6)  ChatGPT helper
203	     ---------------------------------------------------------------- */
204	  export async function callChatApi(messages) {
205	    if (isMockMode()) {
206	      return Promise.resolve({
207	        response: "This is a mock response. Please configure the OpenAI API to use the chat feature.",
208	        success: true
209	      });
210	    }
211	
212	    try {
213	      // Get config from localStorage
214	      const shop = sessionStorage.getItem('shopId') || 'demo-shop';
215	      const storageKey = `appConfig_${shop}`;
216	      const cfg = JSON.parse(localStorage.getItem(storageKey) || '{}');
217	      
218	      // Check if OpenAI is enabled and API key exists
219	      if (!cfg.openai?.enabled || !cfg.openai?.apiKey) {
220	        throw new Error('OpenAI is not enabled or API key is missing');
221	      }
222	      
223	      const headers = await authHeader();
224	      
225	      // Use backend proxy instead of direct OpenAI call for security
226	      const response = await fetch(`${API_BASE}/chat`, {
227	        method: 'POST',
228	        headers,
229	        body: JSON.stringify({ 
230	          messages,
231	          shop_id: shopId()
232	        }),
233	      });
234	      
235	      if (!response.ok) {
236	        throw new Error(await response.text());
237	      }
238	      
239	      return await response.json();
240	    } catch (error) {
241	      console.error('Error calling chat API:', error);
242	      return {
243	        error: error.message,
244	        success: false
245	      };
246	    }
247	  }
248	  
249	  /* ────────────────────────────────────────────────────────────────
250	     7)  Legacy local-mock book helper
251	     ---------------------------------------------------------------- */
252	  function legacyMockBook(appt) {
253	    // Create a unique ID for this appointment
254	    const appointmentId = appt.id || 
255	      `${appt.date}-${appt.start_time}-${appt.worker_id}-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
256	    
257	    const withId = {
258	      ...appt,
259	      id: appointmentId,
260	      shop_id: shopId(),
261	      created_at: new Date().toISOString(),
262	    };
263	    
264	    // Create a new array instead of mutating the existing one
265	    // This is more thread-safe than directly pushing to the array
266	    const updatedAppointments = [...mockAppointments, withId];
267	    
268	    // Replace the original array with the updated one atomically
269	    mockAppointments.length = 0; 
270	    mockAppointments.push(...updatedAppointments);
271	    
272	    // Persist to localStorage if available
273	    try {
274	      const shop = sessionStorage.getItem('shopId') || 'demo-shop';
275	      const storageKey = `mockAppointments_${shop}`;
276	      localStorage.setItem(storageKey, JSON.stringify(updatedAppointments));
277	    } catch (error) {
278	      console.error('Error saving mock appointment to localStorage:', error);
279	    }
280	    
281	    return Promise.resolve({
282	      success: true,
283	      message: 'Appointment saved locally (mock mode)',
284	      id: appointmentId,
285	    });
286	  }
