 439	  // Generate time options for a specific date and worker
 440	  const generateTimeOptions = async (workerId, date) => {
 441	    // Get the day of the week (0 = Sunday, 6 = Saturday)
 442	    const dayOfWeek = new Date(date).getDay();
 443	    
 444	    // Determine business hours based on day of week
 445	    let businessHours;
 446	    
 447	    if (dayOfWeek === 0) { // Sunday
 448	      businessHours = config?.business?.sundayHours || '';
 449	    } else if (dayOfWeek === 6) { // Saturday
 450	      businessHours = config?.business?.saturdayHours || '08:00-14:00';
 451	    } else { // Weekdays (Monday-Friday)
 452	      businessHours = config?.business?.weekdayHours || '07:00-19:00';
 453	    }
 454	    
 455	    // Check if it's a specific holiday
 456	    const jsDate = new Date(date);
 457	    const day = jsDate.getDate().toString().padStart(2, '0');
 458	    const month = (jsDate.getMonth() + 1).toString().padStart(2, '0');
 459	    const dateKey = `${day}/${month}`;
 460	    
 461	    const specificHolidays = config?.business?.specificHolidays || ['25/12', '01/01'];
 462	    if (specificHolidays.includes(dateKey)) {
 463	      businessHours = config?.business?.holidayHours || '';
 464	    }
 465	    
 466	    // If no business hours defined, the business is closed
 467	    if (!businessHours) {
 468	      setAvailableTimes([]);
 469	      return;
 470	    }
 471	    
 472	    // Parse business hours (format: "07:00-19:00")
 473	    const [openTime, closeTime] = businessHours.split('-');
 474	    if (!openTime || !closeTime) {
 475	      setAvailableTimes([]);
 476	      return;
 477	    }
 478	    
 479	    const [startHour, startMinute] = openTime.split(':').map(Number);
 480	    const [endHour, endMinute] = closeTime.split(':').map(Number);
 481	    const interval = config?.business?.appointmentInterval || 30;
 482	    
 483	    // Get existing appointments for this worker and date
 484	    try {
 485	      // Import needed on top of file
 486	      const { fetchAppointments } = await import('../../services/api');
 487	      const appointments = await fetchAppointments(date);
 488	      
 489	      // Filter to get only this worker's appointments
 490	      const workerAppointments = appointments.filter(
 491	        appt => appt.worker_id.toString() === workerId.toString()
 492	      );
 493	      
 494	      // Track all time slots
 495	      const times = [];
 496	      let currentHour = startHour;
 497	      let currentMinute = startMinute;
 498	      
 499	      // Generate all possible time slots based on business hours
 500	      while (currentHour < endHour || (currentHour === endHour && currentMinute < endMinute)) {
 501	        const formattedHour = currentHour.toString().padStart(2, '0');
 502	        const formattedMinute = currentMinute.toString().padStart(2, '0');
 503	        const timeSlot = `${formattedHour}:${formattedMinute}`;
 504	        
 505	        // Check if this time slot conflicts with any existing appointment
 506	        const isAvailable = !workerAppointments.some(appt => {
 507	          // Parse the appointment start time
 508	          const [apptHour, apptMinute] = appt.start_time.split(':').map(Number);
 509	          
 510	          // Calculate start and end times in minutes since midnight
 511	          const apptStartMinutes = apptHour * 60 + apptMinute;
 512	          const apptEndMinutes = apptStartMinutes + (appt.duration || interval);
 513	          
 514	          // Current time slot in minutes since midnight
 515	          const timeSlotMinutes = currentHour * 60 + currentMinute;
 516	          
 517	          // Check if there's an overlap
 518	          return (
 519	            (timeSlotMinutes >= apptStartMinutes && timeSlotMinutes < apptEndMinutes) ||
 520	            (timeSlotMinutes + interval > apptStartMinutes && timeSlotMinutes < apptStartMinutes)
 521	          );
 522	        });
 523	        
 524	        // Add available time slot
 525	        if (isAvailable) {
 526	          times.push(timeSlot);
 527	        }
 528	        
 529	        // Move to next time slot
 530	        currentMinute += interval;
 531	        if (currentMinute >= 60) {
 532	          currentHour += 1;
 533	          currentMinute -= 60;
 534	        }
 535	      }
 536	      
 537	      setAvailableTimes(times);
 538	    } catch (error) {
 539	      console.error('Error fetching appointments:', error);
 540	      // Fallback to simple time generation without filtering
 541	      const times = [];
 542	      let currentHour = startHour;
 543	      let currentMinute = startMinute;
 544	      
 545	      while (currentHour < endHour || (currentHour === endHour && currentMinute < endMinute)) {
 546	        const formattedHour = currentHour.toString().padStart(2, '0');
 547	        const formattedMinute = currentMinute.toString().padStart(2, '0');
 548	        times.push(`${formattedHour}:${formattedMinute}`);
 549	        
 550	        currentMinute += interval;
 551	        if (currentMinute >= 60) {
 552	          currentHour += 1;
 553	          currentMinute -= 60;
 554	        }
 555	      }
 556	      
 557	      setAvailableTimes(times);
 558	    }
 559	  };
