  // Handle worker selection
  const handleWorkerSelect = (worker) => {
    console.log("Selected worker:", worker);

    if (isGuidedMode()) {
      // In guided mode, update state and advance
      setBookingState(prev => {
        const newState = {
          ...prev,
          selectedWorker: worker,
          step: 4
