          const apptStartMinutes = apptHour * 60 + apptMinute;
          const apptEndMinutes = apptStartMinutes + (appt.duration || interval);

          // Current time slot in minutes since midnight
          const timeSlotMinutes = currentHour * 60 + currentMinute;

