            // DD/MM format (assume current year)
            else if (enteredText.match(/^\d{1,2}\/\d{1,2}$/)) {
              const [day, month] = enteredText.split('/');
              parsedDate = new Date();
              parsedDate.setDate(parseInt(day, 10));
              parsedDate.setMonth(parseInt(month, 10) - 1);
