      }));

      // Check if services are available
      const hasServices = config?.services?.items && config.services.items.length > 0;

      if (!hasServices) {
        // Skip service selection if no services are configured
        setBookingState(prev => ({
          ...prev,
          selectedService: 'Consulta',
