        else if (num === 3 && textToSend.trim() === "3") {
          setInput('');
          // Look for last confirmed appointment and download its calendar file
          const lastAppointment = messages.reduce((found, msg) => {
            if (msg.role === 'user' && msg.appointmentId) {
