            (timeSlotMinutes >= apptStartMinutes && timeSlotMinutes < apptEndMinutes) ||
            (timeSlotMinutes + interval > apptStartMinutes && timeSlotMinutes < apptStartMinutes)
          );
        });

        // Add available time slot
