          try {
            // DD/MM/YYYY format
            if (enteredText.match(/^\d{1,2}\/\d{1,2}\/\d{4}$/)) {
              const [day, month, year] = enteredText.split('/');
              parsedDate = new Date(`${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`);
