    let businessHours;

    if (dayOfWeek === 0) { // Sunday
      businessHours = config?.business?.sundayHours || '';
    } else if (dayOfWeek === 6) { // Saturday
      businessHours = config?.business?.saturdayHours || '08:00-14:00';
    } else { // Weekdays (Monday-Friday)
      businessHours = config?.business?.weekdayHours || '07:00-19:00';
