339	                    <Typography color="text.secondary">
340	                      Nenhum serviço cadastrado. Clique em Adicionar Serviço para começar.
341	                    </Typography>
342	                  </TableCell>
343	                </TableRow>
344	              ) : (
345	                currentServices.map((service) => (
346	                  <TableRow key={service.id}>
347	                    <TableCell>{service.name}</TableCell>
348	                    <TableCell align="center">{service.duration}</TableCell>
349	                    <TableCell align="center">R$ {service.price.toFixed(2)}</TableCell>
350	                    <TableCell align="right">
351	                      <IconButton 
352	                        color="primary" 
353	                        size="small" 
354	                        onClick={() => handleEditService(service)}
355	                        sx={{ mr: 1 }}
356	                      >
357	                        <EditIcon />
358	                      </IconButton>
359	                      <IconButton 
360	                        color="error" 
361	                        size="small" 
362	                        onClick={() => handleDeleteService(service.id)}
363	                      >
364	                        <DeleteIcon />
365	                      </IconButton>
366	                    </TableCell>
367	                  </TableRow>
368	                ))
369	              )}
370	            </TableBody>
371	          </Table>
372	        </TableContainer>
373	      </Box>
374	      
375	      {/* Add/Edit Service Dialog */}
376	      <Dialog 
377	        open={serviceDialogOpen} 
378	        onClose={() => setServiceDialogOpen(false)}
379	        maxWidth="sm"
380	        fullWidth
381	      >
382	        <DialogTitle>
383	          {editingService ? 'Editar Serviço' : 'Adicionar Novo Serviço'}
384	        </DialogTitle>
385	        <DialogContent>
386	          <Grid container spacing={2} sx={{ mt: 0.5 }}>
387	            <Grid item xs={12}>
388	              <TextField
389	                label="Nome do Serviço"
390	                fullWidth
391	                value={serviceFormData.name}
392	                onChange={(e) => handleServiceFormChange('name', e.target.value)}
393	                margin="normal"
394	                autoFocus
395	                required
396	              />
397	            </Grid>
398	            <Grid item xs={12} md={6}>
399	              <TextField
400	                label="Duração (minutos)"
401	                type="number"
402	                fullWidth
403	                value={serviceFormData.duration}
404	                onChange={(e) => handleServiceFormChange('duration', parseInt(e.target.value) || 0)}
405	                margin="normal"
406	                InputProps={{ inputProps: { min: 5, step: 5 } }}
407	                required
408	              />
409	              <FormHelperText>
410	                Tempo de duração do serviço em minutos
411	              </FormHelperText>
412	            </Grid>
413	            <Grid item xs={12} md={6}>
414	              <TextField
415	                label="Preço (R$)"
416	                type="number"
417	                fullWidth
418	                value={serviceFormData.price}
419	                onChange={(e) => handleServiceFormChange('price', parseFloat(e.target.value) || 0)}
420	                margin="normal"
421	                InputProps={{ inputProps: { min: 0, step: 0.01 } }}
422	                required
423	              />
424	              <FormHelperText>
425	                Valor cobrado pelo serviço
426	              </FormHelperText>
427	            </Grid>
428	            {serviceError && (
429	              <Grid item xs={12}>
430	                <Alert severity="error">{serviceError}</Alert>
431	              </Grid>
432	            )}
433	          </Grid>
434	        </DialogContent>
435	        <DialogActions sx={{ px: 3, pb: 2 }}>
436	          <Button onClick={() => setServiceDialogOpen(false)}>
437	            Cancelar
438	          </Button>
439	          <Button 
440	            onClick={handleSaveService} 
441	            variant="contained"
442	            color="primary"
443	          >
444	            {editingService ? 'Atualizar' : 'Adicionar'}
445	          </Button>
446	        </DialogActions>
447	      </Dialog>
448	    </Paper>
449	  );
450	}

