  const dayOfWeek = new Date(date).getDay();

  // Determine business hours based on day of week
  let businessHours;

  if (dayOfWeek === 0) { // Sunday
    businessHours = config?.business?.sundayHours || '';
  } else if (dayOfWeek === 6) { // Saturday
    businessHours = config?.business?.saturdayHours || '08:00-14:00';
  } else { // Weekdays (Monday-Friday)
    businessHours = config?.business?.weekdayHours || '07:00-19:00';
  }

  // Check if it's a specific holiday
  const jsDate = new Date(date);
  const day = jsDate.getDate().toString().padStart(2, '0');
  const month = (jsDate.getMonth() + 1).toString().padStart(2, '0');
