            for (let i = 0; i < 14; i++) {
              const date = new Date();
              date.setDate(today.getDate() + i);

              // Get day of week (0 = Sunday, 6 = Saturday)
              const dayOfWeek = date.getDay();

              // Check if business has hours for this day
