              }));

              // Here's the key problem: We need to ensure dates are available immediately
              // Generate date options upfront, using a synchronous approach
              const dates = [];
              const today = new Date();
              const specificHolidays = config?.business?.specificHolidays || ['25/12', '01/01'];

              // Calculate available dates directly instead of using setState which is async
              for (let i = 0; i < 14; i++) {
