          });

          // Also include Brazilian format for matching
          const brFormat = `${day}/${month}/${year}`;

          dates.push({
            value: formattedDate,
            display: displayDate,
            brFormat: brFormat,
            jsDate: new Date(date)
          });

          // Stop after adding 5 fallback dates
          if (dates.length >= 5) break;
        }
