  0	import React, { useState, useEffect, useRef } from 'react';
  1	import PropTypes from 'prop-types';
  2	import { 
  3	  Box, 
  4	  TextField, 
  5	  Button, 
  6	  Typography, 
  7	  Chip,
  8	  Stack,
  9	  Card,
 10	  CardActionArea,
 11	  CardContent
 12	} from '@mui/material';
 13	import { handleMessage, getSuggestedOptions } from '@barber-app/booking-fsm';
 14	import { BookingContext } from '@barber-app/booking-fsm';
 15	import { callChatApi } from '../../services/api';
 16	import { useNotification } from '../ui/NotificationContext';
 17	import { useConfig } from '../../context/ConfigContext';
 18	
 19	
 20	
 21	/**
 22	 * Chatbox component that allows users to book appointments via a chat interface
 23	 */
 24	export default function Chatbox({ onNewAppointment, workers, freeModeAllowed }) {
 25	  // 1) React hooks at the very top:
 26	  const { config, getUserRole } = useConfig();         // ✅ exactly one useConfig()
 27	  const isEnterpriseAccount     = getUserRole() === 'enterprise';
 28	  const shopId                  = sessionStorage.getItem('shopId');
 29	
 30	  const [messages, setMessages]           = useState([]);
 31	  const [input, setInput]                 = useState('');
 32	  const [loading, setLoading]             = useState(false);
 33	  const [showServiceOptions, setShowServiceOptions] = useState(false);
 34	  const [showWorkerOptions,  setShowWorkerOptions]  = useState(false);
 35	  const [showDateOptions,    setShowDateOptions]    = useState(false);
 36	  const [showTimeOptions,    setShowTimeOptions]    = useState(false);
 37	  const [availableTimes,     setAvailableTimes]     = useState([]);
 38	  const [availableDates,     setAvailableDates]     = useState([]);
 39	
 40	  
 41	  
 42	  
 43	  // Track booking flow state
 44	  const [ctx, setCtx] = useState(/** @type {BookingContext} */({
 45	    shop_id: sessionStorage.getItem('shopId'),
 46	    accountType: getUserRole() === 'enterprise' ? 'enterprise' : 'individual',
 47	    workers,
 48	    config,
 49	    step: 0,
 50	    customDuration: 30, // Default 30 minute duration for custom appointments
 51	    lastAppointmentId: null // Track the last booked appointment for calendar download
 52	  }));
 53	  const bookingState = ctx;
 54	  const setBookingState = setCtx;
 55	  const showConfirmOptions = ctx.step === 6;
 56	  const messagesEndRef = useRef(null);
 57	  const { showNotification } = useNotification();
 58	
 59	
 60	  // Get services from config or use defaults
 61	  const getAvailableServices = () => {
 62	    // Check if services are defined in config
 63	    if (config?.services?.items && config.services.items.length > 0) {
 64	      // Use the services from config
 65	      return config.services.items.map(service => service.name);
 66	    }
 67	    
 68	    // Return a single custom consultation option if no services are configured
 69	    return ["Consulta"];
 70	  };
 71	  
 72	  const commonServices = getAvailableServices();
 73	  
 74	  // Helper function to get guided mode setting from config
 75	  const isGuidedMode = () => {
 76	    if (!freeModeAllowed) return true;
 77	  
 78	    const guidedMode = config?.chatbot?.guidedMode !== false; // default: guided
 79	    return guidedMode;
 80	  };
 81	
 82	  const today = new Date();
 83	  const formattedDate = today.toISOString().split('T')[0];
 84	  const workerNames = workers.length > 0 ? workers.map(b => b.name).join(', ') : 'Nenhum profissional disponível';
 85	  
 86	  // Helper function to add minutes to a time string (HH:MM)
 87	  const addMinutes = (timeStr, minutes) => {
 88	    const [hours, mins] = timeStr.split(':').map(Number);
 89	    const date = new Date();
 90	    date.setHours(hours, mins + minutes, 0);
 91	    return date.getHours().toString().padStart(2, '0') + ':' + 
 92	           date.getMinutes().toString().padStart(2, '0');
 93	  };
 94	
 95	  // Scroll to bottom of messages
 96	  const scrollToBottom = () => {
 97	    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
 98	  };
 99	
100	  useEffect(() => {
101	    scrollToBottom();
102	  }, [messages]);
103	
104	  // Reset the chat when the chat mode changes
105	  useEffect(() => {
106	    resetChat();
107	    // eslint-disable-next-line react-hooks/exhaustive-deps
108	  }, [config?.chatbot?.guidedMode, isEnterpriseAccount]);
109	
110	  // Initialize prompt with system message
111	  useEffect(() => {
112	    if (messages.length === 0) {
113	      if (isGuidedMode()) {
114	        console.log("Initializing guided mode chat");
115	        // In guided mode, start with assistant greeting
116	        const assistantGreeting = { 
117	          role: 'assistant', 
118	          content: "Olá! Sou a " + (config?.assistant?.name || "Amanda") + ", assistente virtual de " + (config?.business?.name || "Barbearia Elite") + ". Para começar, poderia me informar seu nome, por favor?" 
119	        };
120	        setMessages([
121	          { role: 'system', content: getPromptText() },
122	          assistantGreeting
123	        ]);
124	        
125	        // Set booking state to name collection
126	        setBookingState(prev => ({
127	          ...prev,
128	          step: 1,
129	          config // Make sure we have the latest config for service checking
130	        }));
131	      } else {
132	        console.log("Initializing free mode chat");
133	        // In free mode, just set the system message
134	        setMessages([{ role: 'system', content: getPromptText() }]);
135	      }
136	    }
137	    // We include messages in deps array because we need to check its length,
138	    // but intentionally omit getPromptText as it would cause unnecessary reruns
139	    // eslint-disable-next-line react-hooks/exhaustive-deps
140	  }, [messages, workerNames, formattedDate]);
141	  useEffect(() => {
142	    /* run when:
143	         • you're in guided mode
144	         • enterprise account
145	         • you're already at step 3 (service chosen)
146	         • and workers have finally been fetched (length > 0)
147	    */
148	    if (
149	      isGuidedMode() &&
150	      isEnterpriseAccount &&
151	      ctx.step === 3 &&
152	      workers.length > 0
153	    ) {
154	      // Show worker options as a message after a small delay
155	      setTimeout(() => {
156	        const workerListMsg = formatWorkerOptionsMessage();
157	        setMessages(prev => [...prev, { role: 'assistant', content: workerListMsg }]);
158	      }, 500);
159	    }
160	    // eslint-disable-next-line react-hooks/exhaustive-deps
161	  }, [workers.length, isEnterpriseAccount, ctx.step]);
162	  // Helper function to format service options as a numbered list message
163	  const formatServiceOptionsMessage = () => {
164	    if (!commonServices || commonServices.length === 0) return '';
165	    
166	    const header = 'Escolha um serviço digitando o número correspondente:';
167	    const options = commonServices.map((service, index) => 
168	      `${index + 1}. ${service}`
169	    ).join('\n');
170	    
171	    return `${header}\n\n${options}`;
172	  };
173	  
174	  // Helper function to format worker options as a numbered list message
175	  const formatWorkerOptionsMessage = () => {
176	    if (!workers || workers.length === 0) return '';
177	    
178	    const header = 'Escolha um profissional digitando o número correspondente:';
179	    const options = workers.map((worker, index) => {
180	      const specialties = worker.specialties && worker.specialties.length > 0 
181	        ? ` (${worker.specialties.join(', ')})` 
182	        : '';
183	      return `${index + 1}. ${worker.name}${specialties}`;
184	    }).join('\n');
185	    
186	    return `${header}\n\n${options}`;
187	  };
188	  
189	  // Helper function to format date options as a numbered list message
190	  const formatDateOptionsMessage = () => {
191	    if (!availableDates || availableDates.length === 0) return '';
192	    
193	    const header = 'Escolha uma data digitando o número correspondente:';
194	    const options = availableDates.map((date, index) => 
195	      `${index + 1}. ${date.display}`
196	    ).join('\n');
197	    
198	    return `${header}\n\n${options}`;
199	  };
200	  
201	  // Helper function to format time options as a numbered list message
202	  const formatTimeOptionsMessage = () => {
203	    if (!availableTimes || availableTimes.length === 0) return '';
204	    
205	    const header = 'Escolha um horário digitando o número correspondente:';
206	    const options = availableTimes.map((time, index) => 
207	      `${index + 1}. ${time}`
208	    ).join('\n');
209	    
210	    return `${header}\n\n${options}`;
211	  };
212	  
213	  const getPromptText = () => {
214	    const businessType = config?.business?.type?.toUpperCase() || 'BARBEARIA';
215	    const businessName = config?.business?.name || 'Barbearia Elite';
216	    const assistantName = config?.assistant?.name?.toUpperCase() || 'AMANDA';
217	    const assistantFullTitle = config?.assistant?.fullTitle || 'Assistente Virtual';
218	    
219	    // Modify the prompt slightly for individual accounts
220	    const isIndividual = !isEnterpriseAccount;
221	    const individualModifier = isIndividual ? `
222	    ## Configuração de Conta Individual
223	    - Nesta configuração, há apenas um profissional disponível
224	    - NUNCA pergunte ao cliente qual profissional ele deseja
225	    - AUTOMATICAMENTE agende com o único profissional disponível: ${workerNames}
226	    - Pule a etapa de escolha de profissional no fluxo de agendamento` : '';
227	    
228	    return `
229	# DIRETRIZES PARA O SISTEMA DE AGENDAMENTO DE ${businessType}
230	
231	## Informações Operacionais
232	Data atual: ${formattedDate}
233	${config?.professionals?.[0]?.plural || 'Profissionais'} disponíveis: ${workerNames}
234	${individualModifier}
235	
236	## Sua Função
237	Você é ${assistantName}, ${assistantFullTitle}, a secretária virtual especializada da ${businessName}. Sua prioridade absoluta é oferecer uma experiência impecável de agendamento, combinando eficiência, empatia e solução de problemas.
238	
239	## Diretrizes de Comunicação e Persona
240	
241	### Tom e Estilo de Comunicação
242	- Comunique-se EXCLUSIVAMENTE em português brasileiro.
243	- Adote um tom caloroso, profissional e personalizado, como uma recepcionista experiente da mais alta categoria.
244	- Use linguagem clara, direta e educada, evitando termos técnicos desnecessários.
245	- Ajuste seu tom com base na interação: mais jovial com clientes informais, mais profissional com clientes formais.
246	- SEMPRE mantenha um tom positivo, mesmo ao lidar com limitações ou conflitos de agenda.
247	
248	### Fluxo de Conversação
249	- Cumprimente o cliente de forma personalizada com base no horário do dia.
250	- Faça perguntas uma de cada vez, evitando sobrecarregar o cliente.
251	- SEMPRE peça uma ação específica do cliente - nunca encerre uma mensagem sem uma pergunta ou solicitação clara.
252	- NUNCA faça o cliente esperar sem necessidade, como dizer "um momento" e depois voltar.
253	- Confirme periodicamente sua compreensão: "Entendi corretamente que você deseja...?"
254	
255	### Interações Personalizadas
256	- Após obter o nome do cliente, dirija-se a ele pelo nome: "Sr. João" ou "Sra. Maria".
257	- Para clientes que retornam, demonstre reconhecimento: "Que bom vê-lo novamente, Sr. Paulo!"
258	- Adapte-se ao nível de formalidade usado pelo cliente (você/tu/senhor).
259	- Use emojis com moderação para tornar a comunicação mais amigável quando apropriado.
260	
261	## Regras de Negócio Específicas
262	
263	### Horários de Funcionamento
264	- Horário de operação: Segunda a Sábado, das ${config?.business?.openHours || '07:00'} às ${config?.business?.closeHours || '19:00'}
265	- ${config?.business?.closedDays?.join?.(', ') || 'Domingo'}: FECHADO
266	- Última marcação permitida: ${config?.business?.lastAppointmentTime || '18:20'} (garantindo tempo para conclusão)
267	
268	### Lógica de Disponibilidade - MUITO IMPORTANTE
269	- PRESUMA QUE TODOS OS HORÁRIOS DENTRO DO HORÁRIO DE FUNCIONAMENTO ESTÃO DISPONÍVEIS
270	- NÃO EXISTE CONCEITO DE "CONSULTAR" OU "VERIFICAR" DISPONIBILIDADE
271	- Os ÚNICOS horários indisponíveis são aqueles em que já existem agendamentos confirmados
272	- Se o cliente solicita um horário dentro do horário de funcionamento, SEMPRE considere disponível
273	- NUNCA diga "vou verificar disponibilidade" ou "um momento enquanto consulto" - isto não existe
274	- NUNCA demore para "procurar" horários disponíveis - isso é instantâneo
275	
276	### Duração e Intervalos de Serviço
277	- Duração PADRÃO do atendimento: ${config?.business?.appointmentDuration || 40} minutos EXATOS
278	- Intervalo OBRIGATÓRIO entre atendimentos: 0 minutos (agendamentos consecutivos são permitidos)
279	- Horários de início permitidos: a cada ${config?.business?.appointmentInterval || 10} minutos (${config?.business?.openHours || '07:00'}, ${addMinutes(config?.business?.openHours || '07:00', config?.business?.appointmentInterval || 10)}, ${addMinutes(config?.business?.openHours || '07:00', (config?.business?.appointmentInterval || 10)*2)}, etc.)
280	
281	### Serviços e Especialidades
282	- Cada ${config?.professionals?.[0]?.singular || 'profissional'} tem especialidades específicas.
283	- Se um cliente pedir um serviço especializado, sugira APENAS ${config?.professionals?.[0]?.plural || 'profissionais'} com essa especialidade.
284	- Serviços VIP têm prioridade - ofereça os melhores horários para clientes VIP ou serviços premium.
285	
286	### Sistema de ${config?.professionals?.[0]?.plural || 'Profissionais'} e Alocação
287	- NUNCA invente ${config?.professionals?.[0]?.plural || 'profissionais'} além dos listados como disponíveis.
288	- NUNCA invente IDs de ${config?.professionals?.[0]?.plural || 'profissionais'} - use SOMENTE os IDs existentes.
289	${isIndividual ? '' : `- Se o cliente não especificar um ${config?.professionals?.[0]?.singular || 'profissional'}, sugira até 3 opções disponíveis.`}
290	- Aplique a lógica de prioridade: clientes regulares têm prioridade com ${config?.professionals?.[0]?.plural || 'profissionais'} específicos.
291	
292	### Regras de Conflito e Disponibilidade
293	- Um ${config?.professionals?.[0]?.singular || 'profissional'} NÃO pode ter dois agendamentos simultâneos ou sobrepostos.
294	- Mantenha o controle de disponibilidade dos ${config?.professionals?.[0]?.plural || 'profissionais'} por dia/hora com máxima precisão.
295	- Aplique bloqueios automáticos: se um ${config?.professionals?.[0]?.singular || 'profissional'} tem agendamento às 14:00, ele NÃO estará disponível novamente até 14:40.
296	
297	## Formatos e Padrões de Dados
298	
299	### Formato de Data e Hora
300	- Formato de data: AAAA-MM-DD (ISO 8601)
301	- Formato de hora: HH:MM (24 horas, SEM SEGUNDOS)
302	- Interpretar corretamente expressões temporais do cliente:
