 87	  // Generate QR code for WhatsApp connection using Evolution API
 88	  const handleGenerateQR = async () => {
 89	    setIsGeneratingQR(true);
 90	    setQrCodeError('');
 91	    
 92	    try {
 93	      const phoneNumber = whatsappConfig.phoneNumber.replace(/\D/g, '');
