155	        Integração com WhatsApp
156	      </Typography>
157	      <Typography variant="body2" color="text.secondary" paragraph>
158	        Configure sua integração com WhatsApp via Evolution API para atendimento automatizado.
159	      </Typography>
160	      <Divider sx={{ my: 3 }} />
161	      
162	      {/* Basic WhatsApp Configuration */}
163	      <Box sx={{ mb: 4 }}>
164	        <Typography variant="h6" gutterBottom color="primary">
165	          Configuração Básica
166	        </Typography>
167	        <Grid container spacing={3}>
168	          <Grid item xs={12}>
169	            <FormControlLabel
170	              control={
171	                <Switch
172	                  checked={whatsappConfig.enabled || false}
173	                  onChange={(e) => handleWhatsAppChange('enabled', e.target.checked)}
174	                />
175	              }
176	              label="Ativar integração com WhatsApp"
