214	                    <CircularProgress size={24} color="inherit" sx={{ mr: 1 }} />
215	                    Gerando QR Code...
216	                  </>
217	                ) : (
218	                  'Gerar QR Code para Conexão'
219	                )}
220	              </Button>
221	              {qrCodeError && (
222	                <Alert severity="error" sx={{ mt: 2 }}>
223	                  {qrCodeError}
224	                </Alert>
225	              )}
226	              <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
227	                Clique para gerar um QR Code que você poderá escanear no WhatsApp para conectar sua conta.
228	              </Typography>
229	            </Grid>
230	        </Grid>
231	      </Box>
232	      
233	      {/* Advanced WhatsApp Configuration */}
234	      <Box sx={{ mb: 4 }}>
235	        <Typography variant="h6" gutterBottom color="primary">
236	          Configuração Avançada
237	        </Typography>
238	        <Grid container spacing={3}>
239	          <Grid item xs={12}>
240	            <FormControlLabel
241	              control={
242	                <Switch
243	                  checked={whatsappConfig.disableGroups || false}
244	                  onChange={(e) => handleWhatsAppChange('disableGroups', e.target.checked)}
245	                  disabled={!whatsappConfig.enabled}
246	                />
247	              }
248	              label="Nunca responder mensagens de grupos"
249	            />
250	            <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
251	              Quando ativado, o bot ignorará todas as mensagens enviadas em grupos do WhatsApp.
252	            </Typography>
253	          </Grid>
254	          
255	          <Grid item xs={12}>
256	            <FormControl component="fieldset" sx={{ mt: 2 }} disabled={!whatsappConfig.enabled}>
257	              <FormLabel component="legend">Modo de Filtragem de Números</FormLabel>
258	              <RadioGroup
259	                value={whatsappConfig.filterMode || 'whitelist'}
260	                onChange={(e) => handleWhatsAppChange('filterMode', e.target.value)}
261	                row
262	              >
263	                <FormControlLabel value="whitelist" control={<Radio />} label="Lista de Permissão" />
264	                <FormControlLabel value="blacklist" control={<Radio />} label="Lista de Bloqueio" />
265	              </RadioGroup>
266	              <FormHelperText>
267	                {whatsappConfig.filterMode === 'whitelist' 
268	                  ? 'Lista de Permissão: Apenas os números listados abaixo receberão respostas do bot' 
269	                  : 'Lista de Bloqueio: Os números listados abaixo nunca receberão respostas do bot'}
270	              </FormHelperText>
271	            </FormControl>
272	          </Grid>
273	          
274	          <Grid item xs={12}>
275	            <TextField
276	              label={whatsappConfig.filterMode === 'whitelist' ? 'Números Permitidos' : 'Números Bloqueados'}
277	              fullWidth
278	              multiline
279	              rows={4}
280	              value={getFilterNumbersString()}
281	              onChange={handleFilterNumbersChange}
282	              margin="normal"
283	              disabled={!whatsappConfig.enabled}
284	              helperText="Digite um número por linha (formato: +5511999999999)"
285	              placeholder="+5511999999999&#10;+5511888888888&#10;+5511777777777"
286	            />
287	          </Grid>
288	        </Grid>
289	      </Box>
290	      
291	      {/* Ads Integration */}
292	      <Box>
293	        <Typography variant="h6" gutterBottom color="primary">
294	          Integração com Anúncios
295	        </Typography>
296	        <Grid container spacing={3}>
297	          <Grid item xs={12}>
298	            <FormControlLabel
299	              control={
300	                <Switch
301	                  checked={whatsappConfig.adIntegration?.enabled || false}
302	                  onChange={(e) => handleAdIntegrationChange('enabled', e.target.checked)}
303	                  disabled={!whatsappConfig.enabled}
304	                />
305	              }
306	              label="Ativar integração com anúncios"
307	            />
308	          </Grid>
309	          
310	          <Grid item xs={12}>
311	            <TextField
312	              label="ID da Campanha de Anúncios"
313	              fullWidth
314	              value={whatsappConfig.adIntegration?.campaignId || ''}
315	              onChange={(e) => handleAdIntegrationChange('campaignId', e.target.value)}
316	              margin="normal"
317	              disabled={!whatsappConfig.enabled || !whatsappConfig.adIntegration?.enabled}
318	              helperText="ID da campanha de anúncios do Facebook/Instagram"
319	            />
320	          </Grid>
321	          
322	          <Grid item xs={12}>
323	            <Alert severity="info" sx={{ mt: 2 }}>
324	              <Typography variant="body2">
325	                A integração com anúncios permite que os usuários que clicarem em um anúncio do tipo 
326	                &quot;Enviar mensagem&quot; sejam automaticamente atendidos pelo bot. É necessário configurar 
327	                corretamente a campanha de anúncios no Facebook Ads Manager.
328	              </Typography>
329	            </Alert>
330	          </Grid>
331	        </Grid>
332	      </Box>
333	      
334	      {/* QR Code Dialog */}
335	      <Dialog open={qrDialogOpen} onClose={() => setQrDialogOpen(false)} maxWidth="sm" fullWidth>
336	        <DialogTitle>Escaneie o QR Code no WhatsApp</DialogTitle>
337	        <DialogContent>
338	          <Box sx={{ display: 'flex', justifyContent: 'center', mb: 2 }}>
339	            {qrCodeURL && (
340	              <img 
341	                src={qrCodeURL} 
342	                alt="WhatsApp QR Code" 
343	                style={{ maxWidth: '100%', height: 'auto' }} 
344	              />
345	            )}
346	          </Box>
347	          <Typography variant="body2" align="center">
348	            Abra o WhatsApp no seu celular, vá em Configurações &gt; Aparelhos conectados &gt; Conectar um aparelho
349	            e escaneie este QR code.
350	          </Typography>
351	          <Alert severity="warning" sx={{ mt: 2 }}>
352	            Este QR code expira em 45 segundos. Se expirar, feche esta janela e gere um novo.
353	          </Alert>
354	          <Alert severity="info" sx={{ mt: 2 }}>
355	            Após escanear, aguarde até que a conexão seja estabelecida. O sistema receberá e enviará mensagens
356	            automaticamente uma vez que o status da instância for atualizado para &quot;CONNECTED&quot;.
357	          </Alert>
358	        </DialogContent>
359	        <DialogActions>
360	          <Button onClick={() => setQrDialogOpen(false)}>Fechar</Button>
361	          <Button onClick={handleGenerateQR} color="primary" startIcon={<QrCodeIcon />}>
362	            Gerar Novo QR Code
363	          </Button>
364	        </DialogActions>
365	      </Dialog>
366	    </Paper>
367	  );
368	}

