          console.log(`Time conflict: ${currentHour}:${currentMinute} conflicts with appointment at ${apptHour}:${apptMinute} (duration: ${appointmentDuration})`);
        }

        return hasOverlap;
      });

      // Add available time slot
      if (isAvailable) {
        times.push(timeSlot);
      }

      // Move to next time slot
