// Function to generate available dates (next 14 days, excluding closed days)
const generateDateOptions = () => {
  const dates = [];
  const today = new Date();
  const specificHolidays = config?.business?.specificHolidays || ['25/12', '01/01'];

  // Generate dates for the next 14 days
  for (let i = 0; i < 14; i++) {
    const date = new Date();
    date.setDate(today.getDate() + i);

    // Get day of week (0 = Sunday, 6 = Saturday)
    const dayOfWeek = date.getDay();

    // Check if business has hours for this day
    let isOpen = false;

    // Check if it's a specific holiday
    const day = date.getDate().toString().padStart(2, '0');
    const month = (date.getMonth() + 1).toString().padStart(2, '0');
    const dateKey = `${day}/${month}`;
    const isHoliday = specificHolidays.includes(dateKey);

    if (isHoliday) {
      // Check for valid holiday hours format (HH:MM-HH:MM)
      isOpen = config?.business?.holidayHours && config.business.holidayHours.includes('-');
    } else if (dayOfWeek === 0) { // Sunday
      // Check for valid Sunday hours format (HH:MM-HH:MM)
      isOpen = config?.business?.sundayHours && config.business.sundayHours.includes('-');
    } else if (dayOfWeek === 6) { // Saturday
      // For Saturday: Use default hours if not specified
      isOpen = true; 
    } else { // Weekday (Monday-Friday)
      // For weekdays: Always open by default
      isOpen = true;
    }

    // Only include dates when business is open
    if (isOpen) {
      // Get date components in local timezone
      const year = date.getFullYear();
      const month = String(date.getMonth() + 1).padStart(2, '0');
      const day = String(date.getDate()).padStart(2, '0');

      // Format date as YYYY-MM-DD without using toISOString() to avoid timezone issues
      const formattedDate = `${year}-${month}-${day}`;

      const displayDate = date.toLocaleDateString('pt-BR', { 
        weekday: 'short', 
        day: '2-digit', 
        month: '2-digit' 
      });

      // Also include Brazilian format for matching
      const brFormat = `${day}/${month}/${year}`;

      dates.push({
        value: formattedDate,
        display: displayDate,
        brFormat: brFormat, // Add Brazilian date format for matching 
        jsDate: new Date(date) // Store a copy of the JS Date object for reliable formatting
      });
    }
  }

  // Ensure we have some dates (even if none were found based on rules)
  if (dates.length === 0) {
    // If no dates were found, add the next 5 weekdays as fallback
    const fallbackToday = new Date();
    for (let i = 0; i < 14; i++) {
      const date = new Date();
      date.setDate(fallbackToday.getDate() + i);

      // Skip weekends in fallback
      const dayOfWeek = date.getDay();
      if (dayOfWeek !== 0 && dayOfWeek !== 6) {
        // Get date components in local timezone
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');

        // Format date as YYYY-MM-DD without using toISOString() to avoid timezone issues
        const formattedDate = `${year}-${month}-${day}`;

        const displayDate = date.toLocaleDateString('pt-BR', { 
          weekday: 'short', 
          day: '2-digit', 
          month: '2-digit' 
        });

        // Also include Brazilian format for matching
        const brFormat = `${day}/${month}/${year}`;

        dates.push({
          value: formattedDate,
          display: displayDate,
          brFormat: brFormat,
          jsDate: new Date(date)
        });

        // Stop after adding 5 fallback dates
        if (dates.length >= 5) break;
      }
    }

    console.log("Added fallback dates since no dates were found based on business hours");
  }

  setAvailableDates(dates);

  return dates; // Return the dates for immediate use if needed
};

