    if (!openTime || !closeTime) {
      console.log("Invalid business hours format:", businessHours);
      setAvailableTimes([]);
      return;
    }

    const [startHour, startMinute] = openTime.split(':').map(Number);
    const [endHour, endMinute] = closeTime.split(':').map(Number);
